"""Traffic generator manager"""
from __future__ import print_function, absolute_import, division,\
    unicode_literals
from builtins import object
from ute_common_store.store import Store
from taf.ul.trs_e2e_fw.lib.traffic.generator.tool_factory import ToolFactory
from taf.ul.trs_e2e_fw.lib.utils.decorators import check_rat
from future import standard_library
standard_library.install_aliases()


class TrafficGeneratorManager(object):
    """Traffic generator manager"""
    store = Store()

    def __init__(self):
        pass

    @check_rat
    def traffic_setup(self, **kwargs):
        """
        # Specify the config section device will be looked in
        """
        alias = kwargs.pop('alias', 'default')
        device = kwargs.pop('device', 'device_1')
        generator_factory_obj = ToolFactory(device)
        tool_object = generator_factory_obj.get_tool_obj()
        tool_object.traffic_setup()
        self.store.add(tool_object, alias)
        print(self.store)

    def traffic_load_config(self, **kwargs):
        """
        # Specify the config section device will be looked in
        """
        alias = kwargs.pop('alias', 'default')
        traffic_object = self.store.get(alias)
        traffic_object.load_config()

    @check_rat
    def traffic_start(self, **kwargs):
        """
            # Specify the config section device will be looked invi ar
        """
        alias = kwargs.pop('alias', 'default')
        profile = kwargs.pop('profile', 'set1')
        traffic_object = self.store.get(alias)
        return traffic_object.traffic_start(profile)

    @check_rat
    def traffic_stop(self, **kwargs):
        """
            # Specify the config section device will be looked in
        """
        alias = kwargs.pop('alias', 'default')
        traffic_object = self.store.get(alias)
        traffic_object.traffic_stop()

    def traffic_teardown(self, **kwargs):
        """Traffic teardown"""
        alias = kwargs.pop('alias', 'default')
        traffic_object = self.store.get(alias=alias)
        traffic_object.traffic_teardown()
        self.store.remove(alias)

    @check_rat
    def traffic_capture_and_replay(self, **kwargs):
        """Traffic capture and replay"""
        capture_interface = kwargs.pop('capture_interface', None)
        replay_interface = kwargs.pop('replay_interface')
        capture_filter = kwargs.pop('capture_filter', '')
        num_pkts_to_send = kwargs.pop('num_pkts_to_send', 1)
        delay = kwargs.pop('delay', 0)
        alias = kwargs.pop('alias', "default")
        pcap_filepath = kwargs.pop('pcap_filepath', None)
        traffic_object = self.store.get(alias)
        print("traffic obj is :{}".format(traffic_object))
        traffic_object.traffic_capture_and_replay(
            capture_interface, replay_interface, capture_filter,
            num_pkts_to_send, delay, pcap_filepath, **kwargs)
